sys_script_include.script:
var EnergirSapRolesUnmapped = Class.create();
EnergirSapRolesUnmapped.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    saprolesnotmapped: function(filter) {
        var unique = [];
        var notuselist = [];
        var latestRecords = {};

        var relCi = new GlideRecord('cmdb_rel_ci');
        relCi.addEncodedQuery('parent.sys_class_name=cmdb_ci_service');
        relCi.query();
        while (relCi.next()) {
            var childSysId = relCi.child.sys_id.toString();
            if (childSysId) {
                unique.push(childSysId);
            }
        }
        if (unique.length > 0) {
            var sapRoles = new GlideRecord('u_cmdb_ci_application_role_sap');
            sapRoles.addEncodedQuery(filter);
            sapRoles.addQuery('sys_id', 'NOT IN', unique);
            sapRoles.query();
            while (sapRoles.next()) {
                var sysid = sapRoles.getUniqueValue();
                var updatedDate = sapRoles.sys_updated_on;

                if (!latestRecords[sysid] || updatedDate > latestRecords[sysid].date) {
                    latestRecords[sysid] = {
                        sys_id: sysid,
                        date: updatedDate
                    };
                }
            }
        }


        for (var sysid in latestRecords) {
            notuselist.push(latestRecords[sysid].sys_id);
        }
        gs.print('La liste des SAP non mappés est: ' + notuselist);
        return notuselist;
    },

    type: 'EnergirSapRolesUnmapped'
});
